update public.products set image_key = case name when 'Naughty Nutella' then 'd-nutella' when 'Triple Chocolate' then 'd-triple' when 'I''m a Gems Baby' then 'd-gems' when 'Sweetheart' then 'd-heart' when 'KitKat-ishh' then 'd-kitkat' when 'Dark Chocolate Fantasy' then 'd-dark' when 'Oreo Dark Crunch' then 'd-oreo' when 'Dark & Milk Delight' then 'd-darkmilk' when 'Dark & White Delight' then 'd-darkwhite' when 'Sprinkled Baby' then 'd-sprinkle' when 'Milk Chocolate Fantasy' then 'd-milk' else image_key end where image_key='desserts';